INSERT INTO `textos` (`id`, `texto`, `page`, `deleted_at`, `updated_at`, `created_at`) VALUES
(1, 'Existimos porque al igual que tú tenemos la misma pasión e interés por jugar. porque somos como tu “Player 2” para acompañarte sin importar el planeta al que esta vez quieras viajar o el enemigo al que estés dispuesto a enfrentar, simplemente, porque al igual que tú, sabemos que ser “gamer” es un estilo de vida.', 'SOBRE NOSOTROS', NULL, NULL, '2018-10-22 19:41:25');
